select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Anything' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Créateur d''applications par IA qui produit sites, applications mobiles et outils internes à partir de descriptions en langage courant, avec hébergement, base de données et paiements.',
  'AI app builder that creates websites, mobile apps and internal tools from plain-language descriptions, with hosting, database and payments.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Pictory AI Video Agent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Créateur vidéo IA dont l''agent vidéo construit une vidéo à partir de votre brief, script, article ou enregistrement, avec voix off, sous-titres et images d''illustration, puis vous laisse l''affiner.',
  'AI video maker whose video agent builds a video from your brief, script, article or recording, with voice-over, captions and stock footage, then lets you refine it.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Clio Work' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'IA juridique pour les cabinets d''avocats : elle analyse vos dossiers, recherche le droit applicable et rédige les documents, chaque réponse étant reliée à sa source.',
  'Legal AI for law firms that analyzes your matters, researches the law and drafts documents, with every answer tied to its source.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Felo' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Assistant de recherche et de création IA multilingue qui explore le web et transforme les résultats en présentations, cartes mentales, documents et pages web.',
  'Multilingual AI search and creation assistant that researches the web and presents findings as slides, mind maps, documents and web pages.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Zerve' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme de données agentique pour les équipes de recherche et d''analyse : des agents IA planifient et exécutent les analyses dans des notebooks, au sein de votre propre infrastructure.',
  'Agentic data platform for research and analytics teams: AI agents plan and run analyses in notebooks inside your own infrastructure.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'QuickBooks Intuit Intelligence' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agents et assistant IA intégrés à QuickBooks qui catégorisent les dépenses, rapprochent les comptes, relancent les factures, signalent les anomalies et répondent aux questions financières.',
  'AI agents and assistant inside QuickBooks that categorize expenses, reconcile books, chase invoices, flag anomalies and answer finance questions.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Notta' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Assistant de réunion IA dont le robot rejoint les appels en ligne pour enregistrer, transcrire en de nombreuses langues et rédiger des résumés avec les actions à mener.',
