select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Colossyan' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme vidéo IA pour les équipes de formation : transforme documents et présentations en vidéos de formation interactives avec avatars IA, traduction et agent IA.',
