  'Zoho''s platform to create, deploy and manage AI agents across Zoho apps, free to use: you pay only for model usage beyond the monthly free tokens.');

select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Anything', 'Pictory AI Video Agent', 'Clio Work', 'Felo', 'Zerve', 'QuickBooks Intuit Intelligence', 'Notta', 'Colossyan', 'Zoho Zia Agents') order by e.name;
